# 1. Sintaxis POSIX (Recomendada) y con palabra function:
mi_funcion() { echo "Hola, $USER"; }
function otra_funcion { echo "Ejecutando función"; }

# 2. Sintaxis en una sola línea (espacios y ';' obligatorios):
una_linea() { echo "En una línea"; uname -r; }

# 3. Eliminar función de la memoria:
unset -f mi_funcion

# Declarar variables locales dentro de funciones:
calcular() {
  local resultado=$(( $1 * $2 ))
  echo "Resultado interno: $resultado"
}
calcular 4 5
echo "Fuera: [$resultado]"  # Salida: [] (no contamina el shell padre)

# Desplazamiento de parámetros con 'shift':
procesar() {
  echo "Primer argumento: $1"
  shift        # Descarta $1 y convierte $2 en $1
  echo "Nuevo primer argumento: $1"
}
